'use strict';
const finishingPDPage='production-finishing-wise-hourly-pd';
const finishingPDFields=[['section','Section / Finishing Man No'],['incharge','Supervisor Name'],['buyer','Buyer'],['style','Style'],['item','Item'],['ironManName','Finishing Man Name'],['cardNo','Card No'],['workingPlan','Working Plan'],['hourlyTarget','Hourly Target'],['remarks','Remarks']];
