function finishingPDSection(value){return String(value||'').replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d)).trim().replace(/\s+/g,' ').replace(/^(?:table|line)[.\s-]*(\d)/i,'$1');}
