function finishingPDCompare(a,b){const dates=String(b.date).split('/').reverse().join('-').localeCompare(String(a.date).split('/').reverse().join('-'));const as=finishingPDNumber(a.hourlyPD.fields?.sl),bs=finishingPDNumber(b.hourlyPD.fields?.sl);return dates||(as!==null&&bs!==null?as-bs:0)||finishingPDTable(a.hourlyPD.fields).localeCompare(finishingPDTable(b.hourlyPD.fields),undefined,{numeric:true,sensitivity:'base'});}
