function finishingPDLoad(record){const data=structuredClone(record.hourlyPD);finishingPDDraft.fields=data.fields||{};const fields=finishingPDDraft.fields;if(!fields.line&&/^Line-|^Unit-/i.test(fields.section||''))fields.line=fields.section;fields.ironManName??=fields.qcName||'';fields.section=finishingPDTable(fields);fields.tableNo=fields.section;fields.date=record.date;finishingPDApplySupervisor(fields);finishingPDDraft.rows=finishingPDComputedRows(data.rows);for(const key of ['targets','differences','achievements'])finishingPDDraft[key]=data[key]||Array(5).fill('');finishingPDEditId=record.id;finishingPDPendingId=null;}
function finishingPDInput(value,attributes,readonly=false){return '<input '+attributes+' value="'+esc(value??'')+'" '+(readonly?'readonly':'')+' autocomplete="off">';}
function finishingPDPaper(readonly=false){finishingPDApplySupervisor();finishingPDDraft.rows=finishingPDComputedRows(finishingPDDraft.rows);return '<section class="finishing-pd-paper" aria-label="Finishing Wise Hourly Production"><h2>FINISHING WISE HOURLY PRODUCTION</h2><div class="finishing-pd-details"><div class="finishing-pd-field"><label for="finishing-pd-date">Date</label>'+finishingPDInput(finishingPDDraft.fields.date||finishingPDToday(),'id="finishing-pd-date" data-finishing-pd-field="date" placeholder="DD/MM/YYYY" maxlength="10"',readonly)+'</div>'+finishingPDFields.map(([key,label])=>'<div class="finishing-pd-field"><label for="finishing-pd-'+key+'">'+label+'</label>'+(key==='section'?finishingPDSectionControl(readonly):finishingPDInput(finishingPDDraft.fields[key],'id="finishing-pd-'+key+'" data-finishing-pd-field="'+key+'" type="'+(['workingPlan','hourlyTarget'].includes(key)?'number':'text')+'" '+(['workingPlan','hourlyTarget'].includes(key)?'min="0" step="1"':'maxlength="300"')+(key==='buyer'?' list="finishing-pd-buyer-options"':key==='style'?' list="finishing-pd-style-options"':''),readonly))+'</div>').join('')+'</div><div class="finishing-pd-table-wrap"><table class="finishing-pd-table"><thead><tr><th scope="col">Hourly</th>'+finishingPDEntryColumns.map(([label])=>'<th scope="col">'+label+'</th>').join('')+'</tr></thead><tbody>'+finishingPDHours.map((hour,row)=>'<tr><th scope="row">'+hour+'</th>'+finishingPDEntryColumns.map(([label,col])=>'<td>'+finishingPDInput(finishingPDDraft.rows[row][col],'type="number" min="0" step="1" data-finishing-pd-row="'+row+'" data-finishing-pd-col="'+col+'" aria-label="'+hour+' '+label+'"',readonly)+'</td>').join('')+'</tr>').join('')+'</tbody><tfoot><tr><th>Total</th>'+finishingPDEntryColumns.map(([,col])=>'<td><output data-finishing-pd-total="'+col+'">'+finishingPDDisplay(finishingPDSum(finishingPDDraft.rows.map(row=>row[col])))+'</output></td>').join('')+'</tr></tfoot></table></div><datalist id="finishing-pd-buyer-options"></datalist><datalist id="finishing-pd-style-options"></datalist>'+(!readonly?'<div class="finishing-pd-save-actions no-print"><button type="button" data-finishing-pd-save data-page-action-required="edit" '+(finishingPDBusy?'disabled':'')+'>'+(finishingPDBusy?'Saving…':'Save')+'</button></div>':'')+'</section>';}
function finishingPDStyleField(readonly=false){return finishingPDPairField('style','Style',readonly);}
function finishingPDPairField(key,title,readonly=false){return '<div class="finishing-pd-field" role="group" aria-label="'+title+'"><span class="finishing-pd-manpower-label">'+title+'</span><div class="finishing-pd-manpower-pair">'+[[key,'1st Machine'],[key+'Last','Last Machine']].map(([field,label])=>'<label for="finishing-pd-'+field+'"><span>'+label+'</span>'+finishingPDInput(finishingPDDraft.fields[field],'id="finishing-pd-'+field+'" data-finishing-pd-field="'+field+'" maxlength="200"'+(key==='style'?' list="finishing-pd-style-options"':''),readonly)+'</label>').join('')+'</div></div>';}
