function finishingPDSuggest(node){const kind=node.dataset.finishingPdField==='buyer'?'buyer':['style','styleLast'].includes(node.dataset.finishingPdField)?'style':null;if(!kind)return;const list=document.getElementById('finishing-pd-'+kind+'-options'),query=node.value.trim().toLocaleLowerCase();if(list)list.innerHTML=query.length<2?'':finishingPDSuggestionValues(kind).filter(value=>value.toLocaleLowerCase().includes(query)).map(value=>'<option value="'+esc(value)+'"></option>').join('');}
function finishingPDDeletePrompt(id){if(!FarnoorAccess.canAction('output','edit'))return;const record=finishingPDRecords().find(row=>row.id===id);if(!record)return;document.getElementById('finishingPDDeleteDialog')?.remove();const dialog=document.createElement('dialog');dialog.id='finishingPDDeleteDialog';dialog.innerHTML='<h3>এই রো ডিলেক্ট করবেন?</h3><p>'+esc(record.date)+' · Table '+esc(finishingPDTable(record.hourlyPD.fields))+'</p><div class="dialog-actions"><button type="button" class="finishing-pd-delete" data-confirm>OK</button><button type="button" data-cancel>Cancel</button></div>';dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.querySelector('[data-confirm]').onclick=async()=>{if(finishingPDBusy)return;const next={...state,records:{...state.records,output:state.records.output.slice()}},target=next.records.output.find(row=>row.id===id&&row.hourlyProduction&&!row.deletedAt);if(!target)return dialog.close();next.records.output=next.records.output.filter(row=>row.id!==id);finishingPDBusy=true;dialog.querySelectorAll('button').forEach(button=>button.disabled=true);dialog.querySelector('[data-confirm]').textContent='Deleting…';try{if(await commit(next,{hourlyDelete:id})){if(finishingPDEditId===id){finishingPDEditId=null;finishingPDPendingId=null;finishingPDDraft.fields={};finishingPDDraft.rows=finishingPDHours.map(()=>Array(5).fill(''));}if(finishingPDSelectedId===id)finishingPDSelectedId=null;dialog.close();renderFinishingPD();toast('ডাটা ডিলেক্ট হয়েছে।');}}finally{finishingPDBusy=false;if(dialog.open){dialog.querySelectorAll('button').forEach(button=>button.disabled=false);dialog.querySelector('[data-confirm]').textContent='OK';}}};document.body.append(dialog);dialog.showModal();}
function finishingPDManpowerTotal(fields,prefix){const op=finishingPDNumber(fields[prefix+'Op']),assistant=finishingPDNumber(fields[prefix+'Hp']);if(op!==null||assistant!==null)return (Number.isFinite(op)?op:0)+(Number.isFinite(assistant)?assistant:0);const old=finishingPDNumber(fields[prefix+'Manpower']);return old!==null&&Number.isFinite(old)?old:'';}
function finishingPDManpowerField(key,label,readonly=false){const prefix=key==='layoutManpower'?'layout':'present';return '<div class="finishing-pd-field finishing-pd-manpower-field" role="group" aria-label="'+label+'"><span class="finishing-pd-manpower-label">'+label+'</span><div class="finishing-pd-manpower-pair">'+[['Op','Operator'],['Hp','Ast. Operator']].map(([suffix,title])=>'<label for="finishing-pd-'+prefix+suffix+'"><span>'+title+'</span>'+finishingPDInput(finishingPDDraft.fields[prefix+suffix],'id="finishing-pd-'+prefix+suffix+'" data-finishing-pd-field="'+prefix+suffix+'" type="number" min="0" step="1"',readonly)+'</label>').join('')+'<span class="finishing-pd-manpower-sum">Total: <output id="finishing-pd-'+prefix+'-total">'+finishingPDDisplay(finishingPDManpowerTotal(finishingPDDraft.fields,prefix))+'</output></span></div></div>';}
// Preserve the template COUNT ranges: P:Y for first/last, P:Z for QC Pass.
function finishingPDCalculate(data){
 const f=data.fields||{},rows=finishingPDComputedRows(data.rows),numbers=rows.map(row=>row.map(finishingPDNumber));
 const count=(c,end)=>numbers.slice(0,end).filter(r=>r[c]!==null&&Number.isFinite(r[c])).length;
 const totals=finishingPDColumns.map((_,c)=>numbers.reduce((sum,r)=>sum+(Number.isFinite(r[c])?r[c]:0),0));
 const finishing=finishingPDNumber(f.hourlyTarget),target=count=>finishing!==null&&Number.isFinite(finishing)?count*finishing:null;
 const first=target(count(0,10)),last=target(count(1,10)),pass=target(count(3,11));
 const targets=[first===null?null:Math.round(first*1.1*1e9)/1e9,last,null,pass,null];
 const differences=totals.map((total,c)=>c===2?totals[1]-total:targets[0]===null?null:Math.round((total-targets[0])*1e9)/1e9);
 const divide=(a,b)=>b!==null&&Number.isFinite(b)&&b!==0?a/b:null;
 const rates=[divide(totals[0],targets[0]),divide(totals[1],targets[1]),null,divide(totals[3],targets[3]),divide(totals[4],totals[2])];
 const op=finishingPDNumber(f.presentOp),hp=finishingPDNumber(f.presentHp),present=op!==null||hp!==null?(op||0)+(hp||0):finishingPDNumber(f.presentManpower)??0;
 return {totals,targets,differences,rates,present};
}
function finishingPDRateClass(rate,c){if(rate===null)return c===2?'finishing-rate-red':'';if(c===4)return 'finishing-rate-cyan';return rate>(c===0?1.1:.9)?'finishing-rate-green':rate>=(c===0?1:.8)?'finishing-rate-yellow':'finishing-rate-red';}
function finishingPDPrintSheet(records){
 records=records.slice().sort(finishingPDCompare);
 const source=v=>'<span class="finishing-pd-value">'+finishingPDDisplay(v)+'</span>',number=v=>v===null||v===undefined||v===''?'':Math.round(v).toString(),rate=v=>v===null||v===undefined?'':Math.round(v*100)+'%';
 const cell=(v,attrs='',input=true)=>'<td '+attrs+'>'+(input?source(v):finishingPDDisplay(v))+'</td>';
 const widths=[4.386,2.924,6.8756,9.2463,7.8632,2.6074,2.5285,2.133,2.5285,2.8051,2.5285,2.5285,2.5285,2.5285,4.8204,...finishingPDHours.map(()=>2.5285),2.5285,2.5285,2.5285,5.7691];
 const calculations=records.map(r=>finishingPDCalculate(r.hourlyPD));
 const groups=records.map((record,index)=>{const d=record.hourlyPD,f=d.fields||{},a=calculations[index],computed=finishingPDComputedRows(d.rows);return finishingPDColumns.map((label,c)=>'<tr>'+(!c?cell(f.incharge,'rowspan="5" class="finishing-incharge"')+cell(f.section,'rowspan="5"'):'')+cell(c===0?f.buyer:c===1?(f.buyerLast||f.buyer):'','class="finishing-buyer"')+cell(c===0?f.style:c===1?(f.styleLast===undefined?f.style:f.styleLast):'','class="finishing-style"')+cell(c===0?f.item:c===1?(f.itemLast===undefined?f.item:f.itemLast):'','class="finishing-item"')+['layoutOp','layoutHp','layoutManpower','presentOp','presentHp','presentManpower'].map(key=>cell(!c?(key==='presentManpower'?a.present:f[key]):'')).join('')+(!c?cell(f.workingPlan,'rowspan="5"'):'')+cell(!c?f.hourlyTarget:'')+cell(number(a.targets[c]))+'<th class="finishing-status finishing-status-'+c+(c===0&&index>0?' finishing-first-later':'')+'">'+label+'</th>'+finishingPDHours.map((_,r)=>cell(computed[r][c])).join('')+cell(number(a.totals[c]),'class="finishing-calculated '+(c===2?'finishing-qc-total':'')+'"',false)+cell(c===2&&a.differences[c]<0?'('+number(-a.differences[c])+')':number(a.differences[c]),'class="finishing-difference '+(c===2?'finishing-qc-total':'')+'"',false)+cell(rate(a.rates[c]),'class="finishing-achievement '+finishingPDRateClass(a.rates[c],c)+'"',false)+(!c?cell(f.remarks,'rowspan="5" class="finishing-remarks"'):'')+'</tr>').join('');}).join('');
 const sumField=key=>finishingPDSum(records.map((r,i)=>key==='presentManpower'?calculations[i].present:r.hourlyPD.fields?.[key]));
 const sumMetric=c=>records.length?calculations.reduce((sum,a)=>sum+a.totals[c],0):null;
 const unitTarget=finishingPDSum(calculations.map(a=>a.targets[3]));
 const summaryRate=c=>{const denominator=c===4?sumMetric(2):unitTarget;return denominator!==''&&denominator!==null&&denominator!==0?sumMetric(c)/denominator:null;};
 const totalRate=summaryRate(3);
 const footer='<tr class="finishing-pd-total"><th colspan="5">Total</th>'+['layoutOp','layoutHp','layoutManpower','presentOp','presentHp','presentManpower'].map(key=>cell(records.length?(sumField(key)||0):'')).join('')+'<td></td>'+cell(sumField('hourlyTarget'))+cell(number(unitTarget))+'<th class="finishing-status-3">Total QC Pass<br>Production</th>'+finishingPDHours.map((_,h)=>cell(records.length?(finishingPDSum(records.map(r=>r.hourlyPD.rows?.[h]?.[3]))||0):'')).join('')+cell(number(sumMetric(3)),'class="finishing-calculated"',false)+cell(number(finishingPDSum(calculations.map(a=>a.differences[3]))),'class="finishing-calculated"',false)+cell(rate(totalRate),'class="finishing-achievement '+finishingPDRateClass(totalRate,3)+'"',false)+'<td></td></tr>';
 return '<article class="finishing-pd-print-sheet"><header><h2>Farnoor Garments Ltd</h2><h3>Finishing Wise Hourly 1st m/c,Last m/c &amp; QC Pass Report</h3><div><b>Date:- <span class="finishing-pd-value">'+esc((records[0]?.date||finishingPDPrintDate||'').replaceAll('/','.'))+'</span></b><strong>1st Machine: <span class="finishing-key-red">&lt;100,</span> <span class="finishing-key-yellow">100&gt;,</span> <span class="finishing-key-green">110/</span> Last Machine &amp; QC Pass: <span class="finishing-key-red">&lt;80,</span> <span class="finishing-key-yellow">80&gt;,</span> <span class="finishing-key-green">90/</span></strong></div></header><table class="finishing-pd-print-table"><colgroup>'+widths.map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup><thead><tr>'+['Line incharge','Line','Buyer','Style','Item'].map(t=>'<th rowspan="2">'+t+'</th>').join('')+'<th colspan="3">Lay Out Man Power</th><th colspan="3">Use Man Power</th>'+['W.<br>Plan','Hourly<br>Target','Total<br>Target','Production<br>Status',...finishingPDHours.map(t=>t.replace('-','-<br>')),'Total','<span class="finishing-difference">Difference</span>','Acv %','Remarks'].map(t=>'<th rowspan="2">'+t+'</th>').join('')+'</tr><tr>'+Array(2).fill(['Op','Hp','Total'].map(t=>'<th>'+t+'</th>').join('')).join('')+'</tr></thead><tbody>'+groups+(records.length?'':'<tr><td colspan="30">Input Report থেকে একটি সেভ করা ইনপুট নির্বাচন করুন।</td></tr>')+footer+'</tbody></table><table class="finishing-pd-summary"><colgroup><col style="width:31%"><col style="width:40%"><col style="width:29%"></colgroup><tbody><tr><th colspan="3">Farnoor Garments Ltd</th></tr><tr><th colspan="3">Finishing Wise 1st m/c,Last m/c &amp; QC Pass Summary</th></tr><tr><th colspan="3">Total Summary</th></tr><tr><th>Unit Target</th><td>'+number(unitTarget)+'</td><th>TARGET %</th></tr>'+finishingPDColumns.map((label,c)=>'<tr class="finishing-summary-'+c+'"><th>Total '+label+'</th><td>'+number(sumMetric(c))+'</td><td>'+rate(summaryRate(c))+'</td></tr>').join('')+'</tbody></table></article>';
}
function finishingPDReport(){const rows=finishingPDRecords(),columns=[['tableNo','Section'],['incharge','Supervisor Name'],['buyer','Buyer'],['style','Style'],['item','Item'],['ironManName','Finishing Man Name'],['cardNo','Card No'],['finishingSection','Finishing Section'],['finishingNewOld','Row'],['finishingStartDate','Finishing Date'],['finishingQty','QTY'],['finishingSizeQty','Size QTY'],['finishingStartTime','Start Time'],['finishingEndDate','End Date'],['finishingEndTime','End Time'],['finishingComplete','Daily Complete Finishing'],['remarks','Remarks']];return '<section class="finishing-pd-report"><h2>Input Report</h2><div class="table-wrap"><table><thead><tr><th>Date</th>'+columns.map(([,label])=>'<th>'+label+'</th>').join('')+'<th>Action</th></tr></thead><tbody>'+rows.map(row=>{const fields=row.hourlyPD.fields||{};return '<tr><td>'+esc(row.date)+'</td>'+columns.map(([key])=>'<td>'+esc(key==='tableNo'?fields.finishingSection||finishingPDTable(fields):key==='finishingNewOld'&&typeof finishingBoardRowSlot==='function'?finishingBoardRowSlot(fields[key]):fields[key]??'')+'</td>').join('')+'<td><button type="button" data-finishing-pd-open="'+esc(row.id)+'">Open</button> <button type="button" data-finishing-pd-select="'+esc(row.id)+'">Print</button> <button type="button" class="finishing-pd-delete" data-page-action-required="edit" data-finishing-pd-delete="'+esc(row.id)+'">▣ Delete</button></td></tr>';}).join('')+(rows.length?'':'<tr><td colspan="9">কোনো সেভ করা ইনপুট নেই।</td></tr>')+'</tbody></table></div></section>';}
