 if(button){finishingPDView=button.dataset.finishingPdView;if(finishingPDView==='new-input'&&finishingPDEditId){finishingPDDraft.fields={};finishingPDDraft.rows=finishingPDHours.map(()=>Array(5).fill(''));for(const key of ['targets','differences','achievements'])finishingPDDraft[key]=Array(5).fill('');finishingPDEditId=null;finishingPDPendingId=null;}if(finishingPDView==='print'){finishingPDSelectedId=null;finishingPDPrintDate||=finishingPDToday();}renderFinishingPD();return;}
