 return [...new Set([...finishingPDRecords().map(r=>r.hourlyPD.fields?.[key]),...finishingBoardRows.map(r=>r.fields[key])].map(v=>String(v??'').trim()).filter(Boolean))].filter(v=>v.toLocaleLowerCase().includes(q));
