  for(const key of ['finishingQty','finishingSizeQty','finishingComplete'])if(String(f[key]??'').trim()){const n=finishingPDNumber(f[key]);if(n===null||!Number.isFinite(n)||n<0)throw Error('QTY, Size QTY ও Daily Complete Finishing-এ সঠিক সংখ্যা লিখুন।');f[key]=String(n);}
  const staged=finishingBoardEditingRow&&finishingBoardRows.includes(finishingBoardEditingRow)&&finishingBoardSameSlot(finishingBoardEditingRow.fields,f)?finishingBoardEditingRow:f.ironManName?finishingBoardRows.find(r=>finishingBoardSameSlot(r.fields,f)):null,date=staged?.fields.date||finishingPDDraft.fields.date||finishingPDToday();
