 const records=finishingPDRecords().slice().sort((a,b)=>String(a.updatedAt||a.createdAt).localeCompare(String(b.updatedAt||b.createdAt)));
 for(const row of records){const f=row.hourlyPD.fields||{};if(f.workerProfile==='1'&&f.ironManName){const n=Number(f.sl);if(Number.isInteger(n)&&n>0)merge({name:f.ironManName,card:f.cardNo||finishingWorkerDefaultCards[f.ironManName]||'',sl:n,section:f.finishingSection||'',previousCard:f.workerPreviousCard||''});}}
