 const previousOverride=finishingWorkerOverrides.find(w=>w.card===originalCard||w.name===originalCard);const worker={name,card,sl,section,previousCard:previousOverride?.previousCard||original?.card||''};finishingWorkerOverrides=finishingWorkerOverrides.filter(w=>w.name!==original?.name&&w.card!==originalCard&&w.card!==card);finishingWorkerOverrides.push(worker);
